// IntentClassifierService.swift
// STT
//
// 3-stage on-device intent classification pipeline.
// Mirrors the architecture in IntentClassifier/scripts/nlu/classifier.py
// and IntentClassifier/scripts/nlu/semantic.py.
//
// Stage 1 — Keyword rules   (KeywordMatcher)         sync, ~0 ms
// Stage 2 — TF-IDF + LogReg (CoreML intent model)    async, ~2 ms
// Stage 3 — Semantic rescue (MiniLM-L6-v2 via CoreML) async, ~8 ms
//
// Stage 2 primary: IntentClassifier.mlpackage (generated by export_coreml.py).
// Stage 2 fallback: intent_classifier_weights.json (pure-Swift reimplementation,
//   used automatically if the .mlpackage is absent from the bundle).
//
// Stage 3 activates only when Stage 2 returns low confidence or "Default Fallback
// Intent". Both SemanticEmbedder and SemanticClassifier return nil from their
// inits if their bundle artifacts are missing — Stage 3 is skipped silently.

import CoreML
import Foundation
import os.log

// MARK: - Result type

public struct ClassificationResult: Sendable {
    public let label: String
    public let confidence: Double
    /// True when Stage 3 (MiniLM semantic rescue) produced this result.
    public let semanticRescue: Bool
}

// MARK: - Service

public final class IntentClassifierService: @unchecked Sendable {

    // MARK: - Singleton

    public static let shared = IntentClassifierService()

    // MARK: - Stage 1

    private let keywordMatcher = KeywordMatcher()

    // MARK: - Stage 2 — CoreML (primary)

    private let coreMLModel: MLModel?

    // MARK: - Stage 2 — JSON weights fallback

    private let labels: [String]
    private let vocab: [String: Int]
    private let idf: [Double]
    private let coef: [[Double]]
    private let intercept: [Double]

    // MARK: - Stage 3

    private let semanticEmbedder: SemanticEmbedder?
    private let semanticClassifier: SemanticClassifier?

    // MARK: - Thresholds

    private let confThreshold: Double
    private let confGapThreshold: Double
    private let genaiBaseURL: String
    private static let semanticThreshold: Double = 0.55

    private static let fallbackLabel = "Default Fallback Intent"

    private let logger = Logger(subsystem: "com.stt.module", category: "IntentClassifier")

    // MARK: - Init

    private init() {
        // -- Stage 2 primary: CoreML --
        // Xcode compiles .mlpackage → .mlmodelc at build time; try compiled form first.
        let intentURL = Bundle.main.url(forResource: "IntentClassifier", withExtension: "mlmodelc")
                     ?? Bundle.main.url(forResource: "IntentClassifier", withExtension: "mlpackage")
        if let modelURL = intentURL {
            let config = MLModelConfiguration()
            config.computeUnits = .all
            coreMLModel = try? MLModel(contentsOf: modelURL, configuration: config)
        } else {
            coreMLModel = nil
        }

        // -- Stage 2 fallback: JSON weights --
        guard
            let url = Bundle.main.url(forResource: "intent_classifier_weights",
                                      withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let obj  = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        else {
            fatalError("IntentClassifierService: intent_classifier_weights.json not found in bundle.")
        }
        labels           = obj["labels"]            as! [String]
        vocab            = obj["vocab"]              as! [String: Int]
        idf              = obj["idf"]                as! [Double]
        coef             = obj["coef"]               as! [[Double]]
        intercept        = obj["intercept"]          as! [Double]
        confThreshold    = obj["conf_threshold"]     as? Double ?? 0.70
        confGapThreshold = obj["conf_gap_threshold"] as? Double ?? 0.20
        genaiBaseURL     = obj["genai_base_url"]     as? String ?? ""

        // -- Stage 3: semantic rescue --
        semanticEmbedder   = SemanticEmbedder()
        semanticClassifier = SemanticClassifier()

        let stage2 = coreMLModel != nil ? "CoreML" : "JSON weights"
        let stage3 = semanticEmbedder != nil ? "enabled" : "disabled (artifacts missing)"
        Logger(subsystem: "com.stt.module", category: "IntentClassifier")
            .info("IntentClassifier ready — Stage2: \(stage2), Stage3 semantic: \(stage3)")
    }

    // MARK: - Public API

    /// Full 3-stage async classification. Use this from NLUEngine.
    /// Returns `semanticRescue: true` when Stage 3 saved a low-confidence Stage 2 result.
    public func classifyAsync(_ text: String) async -> ClassificationResult {
        // Stage 1
        if let kw = keywordMatcher.match(text) {
            return ClassificationResult(label: kw.label, confidence: kw.confidence, semanticRescue: false)
        }

        // Stage 2 — run off the current actor to avoid blocking the main thread
        let (stage2Label, stage2Conf) = await Task.detached(priority: .userInitiated) { [self] in
            self.stage2Classify(text)
        }.value
        let stage2Failed = stage2Label == Self.fallbackLabel || stage2Conf < confThreshold

        if !stage2Failed {
            return ClassificationResult(label: stage2Label, confidence: stage2Conf, semanticRescue: false)
        }

        // Stage 3 — only runs when Stage 2 is uncertain
        if let embedder = semanticEmbedder, let head = semanticClassifier,
           let embedding = await embedder.embed(text) {
            let (semLabel, semConf) = head.classify(embedding)
            if semLabel != Self.fallbackLabel && semConf >= Self.semanticThreshold {
                logger.info("Semantic rescue: '\(text)' → \(semLabel) (\(String(format: "%.2f", semConf)))")
                return ClassificationResult(label: semLabel, confidence: semConf, semanticRescue: true)
            }
        }

        return ClassificationResult(label: stage2Label, confidence: stage2Conf, semanticRescue: false)
    }

    /// Sync Stages 1+2 only. Used by `predict()` and legacy callers.
    public func classify(_ text: String) -> (label: String, confidence: Double) {
        if let kw = keywordMatcher.match(text) { return (kw.label, kw.confidence) }
        return stage2Classify(text)
    }

    /// Classify and apply confidence/gap thresholds, returning an `IntentResult`.
    /// Prefer `classifyAsync` from async contexts for full semantic rescue.
    public func predict(_ text: String) -> IntentResult {
        let (label, conf) = classify(text)
        if conf >= confThreshold {
            let probs  = softmax(stage2Logits(text))
            var sorted = probs.enumerated().map { ($0.offset, $0.element) }
            sorted.sort { $0.1 > $1.1 }
            let gap = conf - (sorted.count > 1 ? sorted[1].1 : 0.0)
            if gap >= confGapThreshold {
                return .intent(label: label, confidence: conf)
            }
        }
        return .genai(url: genaiURL(for: text), confidence: conf)
    }

    /// GenAI fallback URL for an unrecognised query.
    public func genaiURL(for text: String) -> URL {
        let encoded = text.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? text
        return URL(string: genaiBaseURL + encoded) ?? URL(string: "https://genai.yourcompany.com")!
    }

    // MARK: - Stage 2 implementation

    /// Tries CoreML first; falls back to pure-Swift TF-IDF + LogReg.
    private func stage2Classify(_ text: String) -> (label: String, confidence: Double) {
        if let model = coreMLModel, let result = coreMLClassify(text, model: model) {
            return result
        }
        // JSON weights fallback
        let probs = softmax(tfidfLogits(text))
        let top   = probs.indices.max(by: { probs[$0] < probs[$1] })!
        return (labels[top], probs[top])
    }

    // MARK: - CoreML Stage 2

    private func coreMLClassify(_ text: String, model: MLModel) -> (String, Double)? {
        // CoreML model (generated by export_coreml.py via NeuralNetworkBuilder) expects:
        //   input  : "tfidf_vector" — Float32 array of length n_features (same as idf count)
        //   outputs: "classProbability" dict, "label" string
        let vec = tfidfVector(for: text)   // [Double], length == idf.count
        let n   = vec.count
        guard n > 0,
              let arr = try? MLMultiArray(shape: [n as NSNumber], dataType: .float32)
        else { return nil }
        for i in 0..<n { arr[i] = NSNumber(value: Float(vec[i])) }

        guard
            let input    = try? MLDictionaryFeatureProvider(dictionary: [
                "tfidf_vector": MLFeatureValue(multiArray: arr)
            ]),
            let output   = try? model.prediction(from: input),
            // dictionaryValue returns [AnyHashable: Any] with NSNumber probability values.
            let probDict = output.featureValue(for: "classProbability")?.dictionaryValue
                           as? [String: NSNumber]
        else { return nil }

        guard let best = probDict.max(by: { $0.value.doubleValue < $1.value.doubleValue })
        else { return nil }
        return (best.key, best.value.doubleValue)
    }

    // MARK: - JSON weights TF-IDF (Stage 2 fallback)

    private func tfidfLogits(_ text: String) -> [Double] {
        return coef.indices.map { c in
            zip(coef[c], tfidfVector(for: text)).reduce(intercept[c]) { $0 + $1.0 * $1.1 }
        }
    }

    // Used only by predict() gap check when CoreML is unavailable.
    private func stage2Logits(_ text: String) -> [Double] {
        if coreMLModel != nil { return [] }  // gap check not applicable on CoreML path
        return tfidfLogits(text)
    }

    private func tfidfVector(for text: String) -> [Double] {
        let tokens = tokenize(text)
        var termCounts: [Int: Int] = [:]
        for token in tokens {
            if let idx = vocab[token] { termCounts[idx, default: 0] += 1 }
        }
        var vec = [Double](repeating: 0.0, count: idf.count)
        for (idx, count) in termCounts {
            vec[idx] = (1.0 + log(Double(count))) * idf[idx]  // sublinear TF
        }
        return l2Normalize(vec)
    }

    private func tokenize(_ text: String) -> [String] {
        let lower = text.lowercased()
        let words = lower.components(separatedBy: CharacterSet.alphanumerics.inverted)
                         .filter { !$0.isEmpty }
        var tokens = words
        for i in words.indices.dropLast() {
            tokens.append(words[i] + " " + words[i + 1])
        }
        return tokens
    }

    // MARK: - Math helpers

    private func softmax(_ logits: [Double]) -> [Double] {
        guard !logits.isEmpty else { return [] }
        let maxVal = logits.max()!
        let exps   = logits.map { exp($0 - maxVal) }
        let sum    = exps.reduce(0, +)
        return sum == 0 ? logits.map { _ in 1.0 / Double(logits.count) } : exps.map { $0 / sum }
    }

    private func l2Normalize(_ vec: [Double]) -> [Double] {
        let norm = sqrt(vec.reduce(0) { $0 + $1 * $1 })
        guard norm > 0 else { return vec }
        return vec.map { $0 / norm }
    }
}
